import React, { useState } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

function Login() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [loginType, setLoginType] = useState("user");
  const [message, setMessage] = useState(null);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      // 🔹 POST request to your backend login API
      const response = await axios.post("http://localhost:9091/api/login", {
        username,
        password,
        loginType,
      });

      if (response.data === "Login successful") {
        // ✅ Save user info
        localStorage.setItem("username", username);
        localStorage.setItem("role", loginType);

        setMessage({ type: "success", text: "Login successful!" });

        // 🔹 Redirect based on role
        if (loginType === "admin") {
          navigate("/admin");
        } else {
          navigate("/shop");
        }
      } else {
        setMessage({ type: "error", text: response.data });
      }
    } catch (error) {
      console.error("Login Error:", error);
      setMessage({
        type: "error",
        text: "Invalid credentials or server error.",
      });
    }
  };

  return (
    <div
      className="relative min-h-screen flex items-center justify-center bg-cover bg-center p-4"
      style={{ backgroundImage: "url('/medical.jpg')" }}
    >
      {/* Background Overlay */}
      <div className="absolute inset-0 bg-black opacity-30"></div>

      {/* Login Box */}
      <div className="relative z-10 bg-white/20 backdrop-blur-lg p-8 rounded-xl shadow-2xl w-full max-w-md border border-white/30">
        <h2 className="text-3xl font-bold text-center text-white mb-6 drop-shadow-lg">
          Login
        </h2>

        <p className="text-xs text-gray-200 text-center mb-4">
          Select your login type and enter credentials.
        </p>

        {/* Login Type */}
        <div className="mb-4">
          <label className="block text-sm font-medium text-gray-100 mb-1">
            Login Type
          </label>
          <select
            value={loginType}
            onChange={(e) => setLoginType(e.target.value)}
            className="w-full px-3 py-2 rounded-lg border border-gray-300 bg-white/70 focus:ring-indigo-500 focus:border-indigo-500"
          >
            <option value="user">User</option>
            <option value="admin">Admin</option>
          </select>
        </div>

        {/* Login Form */}
        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className="block text-sm font-medium text-gray-100 mb-1">
              Username
            </label>
            <input
              type="text"
              required
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg bg-white/70 focus:bg-white focus:ring-indigo-500 focus:border-indigo-500"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-100 mb-1">
              Password
            </label>
            <input
              type="password"
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full px-4 py-2 border border-gray-300 rounded-lg bg-white/70 focus:bg-white focus:ring-indigo-500 focus:border-indigo-500"
            />
          </div>

          <button
            type="submit"
            className="w-full mt-6 px-4 py-2 bg-indigo-600 text-white font-semibold rounded-lg hover:bg-indigo-700 transition duration-200"
          >
            Login
          </button>
        </form>

        {message && (
          <div
            className={`p-3 mt-4 rounded-lg text-sm text-center ${
              message.type === "error"
                ? "bg-red-100 text-red-700"
                : "bg-green-100 text-green-700"
            }`}
          >
            {message.text}
          </div>
        )}
      </div>
    </div>
  );
}

export default Login;
